import React, {
  createContext,
  Fragment,
  memo,
  ReactNode,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import { usePrefixCls } from "../__builtins__";
import ArrayBase, { ArrayBaseMixins } from "../ArrayBase";
import {
  Pagination,
  PaginationProps,
  Space,
  Table,
  TableProps,
} from "@arco-design/web-react";
import { ObjectField, observer, RecursionField, useField, useForm } from "@formily/react";
import { ArrayField, onFormSubmitValidateEnd } from "@formily/core";
import { FormPath, isBool, isFn } from "@formily/shared";
import { SortableContainer, SortableElement } from "react-sortable-hoc";
import {
  isColumnComponent,
  useAddition,
  useArrayTableColumns,
  useArrayTableSources,
} from "./shared/parseSchema";

import { useParseJSXColumns } from "./shared/parseJSX";
import { TableColumnProps } from "./interface";
import { isEqual } from "lodash";

type ComposedArrayTable = React.FC<React.PropsWithChildren<TableProps<any>>> &
  ArrayBaseMixins & {
    Column?: React.FC<React.PropsWithChildren<TableColumnProps>>;
  };

interface IArrayTablePaginationProps extends PaginationProps {
  dataSource?: any[];
  children?: (
    dataSource: any[],
    pagination: React.ReactNode
  ) => React.ReactElement;
}

interface PaginationAction {
  totalPage?: number;
  currentPage?: number;
  pageSize?: number;
  changePage?: (page: number) => void;
}

const SortableRow = SortableElement((props: any) => <tr {...props} />);
const SortableBody = SortableContainer((props: any) => <tbody {...props} />);

const PaginationContext = createContext<PaginationAction>({});
export const usePagination = () => useContext(PaginationContext);

const schedulerRequest = {
  request: null,
};

const prefix = "formily-array-table";

const ArrayTablePagination: React.FC<IArrayTablePaginationProps> = (props) => {
  const [current, setCurrent] = useState(1);
  const prefixCls = usePrefixCls(prefix);
  const pageSize = props.pageSize || 10;
  const size = props.size || "default";
  const dataSource = props.dataSource || [];
  const startIndex = (current - 1) * pageSize;
  const endIndex = startIndex + pageSize - 1;
  const total = dataSource?.length || 0;
  const totalPage = Math.ceil(total / pageSize);
  const formEffectId = useState(Date.now().toString());
  const currentRef = useRef(current);
  currentRef.current = current;

  const field = useField();
  const form = useForm();

  useEffect(() => {
    if (form && field) {
      form.addEffects(formEffectId, () => {
        onFormSubmitValidateEnd((form) => {
          if (form.errors && form.errors.length > 0) {
            const firstArrayError = form.errors.find(error => {
              return !!error.path?.startsWith(field.path.toString());
            })
            // 取到下标
            if (firstArrayError) {
              const firstArrayErrorPath = new FormPath(firstArrayError.path || '');
              const index = firstArrayErrorPath.slice(field.path.length, firstArrayErrorPath.length - 1)?.toString() || 0;
              const firstErrorPage = Math.ceil((Number(index) + 1) / pageSize);
              if (!Number.isNaN(firstErrorPage) && Math.ceil((Number(index) + 1) / pageSize) !== currentRef.current) {
                setCurrent(firstErrorPage);
              }
            }
          }
        })
      })
    }
    return () => {
      form.removeEffects(formEffectId);
    }
  }, [field, form])

  const handleChange = (current: number) => {
    setCurrent(current);
  };

  useEffect(() => {
    if (totalPage > 0 && totalPage < current) {
      handleChange(totalPage);
    }
  }, [totalPage, current]);

  const renderPagination = () => {
    if (totalPage <= 1) {
      return;
    }
    return (
      <div className={`${prefixCls}-pagination`}>
        <Space>
          {/* <StatusSelect
            value={current}
            pageSize={pageSize}
            onChange={handleChange}
            options={pages}
            notFoundContent={false}
          /> */}
          <Pagination
            {...props}
            pageSize={pageSize}
            current={current}
            total={dataSource.length}
            size={size}
            // showSizeChanger={false}
            onChange={handleChange}
          />
        </Space>
      </div>
    );
  };

  return (
    <Fragment>
      <PaginationContext.Provider
        value={{ totalPage, pageSize, changePage: handleChange, currentPage: current }}
      >
        {props.children?.(
          dataSource?.slice(startIndex, endIndex + 1),
          renderPagination()
        )}
      </PaginationContext.Provider>
    </Fragment>
  );
};

const addTdStyles = (node: HTMLElement, prefixCls: string) => {
  const helper = document.body.querySelector(`.${prefixCls}-sort-helper`);
  if (helper) {
    const tds = node.querySelectorAll("td");
    requestAnimationFrame(() => {
      helper.querySelectorAll("td").forEach((td, index) => {
        if (tds[index]) {
          td.style.width = getComputedStyle(tds[index]).width;
        }
      });
    });
  }
};
const WrapperComp = (ref) => (props: any) => {
  const prefixCls = usePrefixCls(prefix);
  const field = useField<ArrayField>();
  return (
    <SortableBody
      useDragHandle
      lockAxis="y"
      helperClass={`${prefixCls}-sort-helper`}
      helperContainer={() => ref.current?.querySelector("tbody")}
      onSortStart={({ node }) => {
        addTdStyles(node as HTMLElement, prefixCls);
      }}
      onSortEnd={({ oldIndex, newIndex }) => {
        field.move(oldIndex, newIndex);
      }}
      {...props}
    />
  );
};

const RowComp = (props: any) => {
  const { record } = props;
  const array = ArrayBase.useArray?.();
  const index = array?.field?.value?.indexOf(record.__ORIGIN_DATA) || 0;
  return <SortableRow {...props} index={index} />;
};

export const SchemaTable = observer((props: TableProps<any>) => {
  const ref = useRef<HTMLDivElement>(null);
  const field = useField<ArrayField>();
  const prefixCls = usePrefixCls("formily-array-table");
  const dataSource = Array.isArray(field.value) ? field.value.slice() : [];

  const sources = useArrayTableSources();
  const columns = useArrayTableColumns(dataSource, field, sources);
  const addition = useAddition();

  const pagination = isBool(props.pagination) ? {} : props.pagination;

  const defaultRowKey = (record: any) => dataSource.indexOf(record);

  return (
    <ArrayTablePagination {...pagination} dataSource={dataSource}>
      {(dataSource, pager) => (
        <div ref={ref} className={prefixCls}>
          <ArrayBase mode="schema">
            <Table
              size="small"
              border
              rowKey={defaultRowKey}
              {...props}
              onChange={() => { }}
              pagination={false}
              columns={columns}
              data={dataSource}
              components={{
                body: {
                  tbody: WrapperComp(ref),
                  row: RowComp,
                },
              }}
            />
            <div style={{ marginTop: 5, marginBottom: 5 }}>{pager}</div>
            {sources.map((column, key) => {
              // 专门用来承接对Column的状态管理
              if (!isColumnComponent(column.schema)) {
                return;
              }
              return React.createElement(RecursionField, {
                name: column.name,
                schema: column.schema,
                onlyRenderSelf: true,
                key,
              });
            })}
            {addition}
          </ArrayBase>
        </div>
      )}
    </ArrayTablePagination>
  );
});


const JSXRowComp = memo(({ fieldProps, ...props }: any) => {
  const { record } = props;
  const array = ArrayBase.useArray?.();
  const dataSource = Array.isArray(array?.field?.value) ? array?.field?.value.slice() : [];
  const index = dataSource?.indexOf(record.__ORIGIN_DATA) || 0;

  return (
    <ArrayBase.Item index={index} record={() => dataSource?.[index]}>
      <ObjectField {...fieldProps} name={index}>
        <SortableRow {...props} index={index} />
      </ObjectField>
    </ArrayBase.Item>
  );
}, (pre, next) => {
  const getColumns = (props: any) => {
    const children = props?.children || [];
    const columns = children.map(it => {
      const column = it?.props?.column;
      if (!column) {
        return null;
      }
      return {
        title: column?.title,
        key: column?.key,
        dataIndex: column?.dataIndex,
      };
    });
    return columns;
  }
  const prevColumns = getColumns(pre);
  const nextColumns = getColumns(next);

  return pre.record.__ORIGIN_DATA === next.record.__ORIGIN_DATA && isEqual(prevColumns, nextColumns);
});

export const JSXTable = observer(
  (props: TableProps<any> & Omit<ExtraArrayTableProps, 'mode'>) => {
    const ref = useRef<HTMLDivElement>(null);
    const field = useField<ArrayField>();
    const prefixCls = usePrefixCls("formily-array-table");
    const dataSource = Array.isArray(field.value) ? field.value.slice() : [];
    const pagination = isBool(props.pagination) ? {} : props.pagination;
    const defaultRowKey = (record: any) => dataSource.indexOf(record);
    const { columns, addition, sourceColumns } = useParseJSXColumns(props.children);
    const { additionPosition = 'paginationBottom' } = props;

    const tableCustomComponents = useMemo(() => {
      return {
        body: {
          tbody: WrapperComp(ref),
          row: JSXRowComp,
        },
      }
    }, [])

    return (
      <ArrayTablePagination {...pagination} dataSource={dataSource}>
        {(dataSource, pager) => (
          <div ref={ref} className={prefixCls}>
            <ArrayBase mode="jsx">
              <Table
                size="small"
                border
                rowKey={defaultRowKey}
                {...props}
                onChange={() => { }}
                pagination={false}
                columns={columns}
                data={dataSource}
                components={tableCustomComponents}
              />
              {additionPosition === 'paginationTop' && addition}
              {pager && <div style={{ marginTop: 5 }}>{pager}</div>}
              {sourceColumns}
              {additionPosition === 'paginationBottom' && addition}
            </ArrayBase>
          </div>
        )}
      </ArrayTablePagination>
    );
  }
);

interface ExtraArrayTableProps {
  mode: "jsx" | "schema";
  children?: ReactNode;
  /**
   * 分页器显示时，增加按钮默认展示在分页器上还是下
   */
  additionPosition?: 'paginationTop' | 'paginationBottom'
}

const ArrayTable: ComposedArrayTable = (
  props: TableProps<any> & ExtraArrayTableProps
) => {
  const { mode, ...rest } = props;
  if (props.mode === "jsx") {
    return <JSXTable {...rest} />;
  } else {
    return <SchemaTable {...rest} />;
  }
};

ArrayTable.displayName = "ArrayTable";

ArrayTable.Column = (props) => <Fragment>{props.children}</Fragment>;

ArrayTable.Column.displayName = "ArrayTableColumn";

ArrayBase.mixin(ArrayTable);

const ArrayBaseAddition = ArrayBase.Addition!;

const Addition: ArrayBaseMixins["Addition"] = (props) => {
  const array = ArrayBase.useArray!();
  const { totalPage = 0, pageSize = 10, changePage, currentPage = 1, } = usePagination();
  return (
    <ArrayBaseAddition
      defaultValue={{}}
      {...props}
      onClick={(e) => {
        // 如果添加数据后将超过当前页，则自动切换到添加页
        const total = array?.field?.value?.length || 0;
        if (total > currentPage * pageSize && isFn(changePage)) {
          if (total === totalPage * pageSize + 1) {
            changePage(totalPage + 1);
          } else {
            changePage(totalPage);
          }
        }
        props.onClick?.(e);
      }}
    />
  );
};

Addition.displayName = "ArrayTableAddition";

ArrayTable.Addition = Addition;

export default ArrayTable;
